struct TreeNode {
    int val;
    struct TreeNode *left;
    struct TreeNode *right;
};

static struct TreeNode *new_node(int value) {
    struct TreeNode *node = (struct TreeNode *)malloc(sizeof(struct TreeNode));
    if (!node) exit(EXIT_FAILURE);
    node->val = value;
    node->left = NULL;
    node->right = NULL;
    return node;
}

static const char *skip_ws(const char *p) {
    while (*p && isspace((unsigned char)*p)) ++p;
    return p;
}

static int next_value(const char **pp, int *value) {
    const char *p = skip_ws(*pp);

    if (*p == '\0' || *p == ']') {
        *pp = p;
        return -1;
    }

    if (strncmp(p, "null", 4) == 0) {
        p += 4;
        p = skip_ws(p);
        if (*p == ',') ++p;
        *pp = p;
        return 0;
    }

    char *end = NULL;
    long v = strtol(p, &end, 10);
    if (end == p) return -1;

    p = skip_ws(end);
    if (*p == ',') ++p;
    *pp = p;
    *value = (int)v;
    return 1;
}

static struct TreeNode *parse_tree(const char *input) {
    const char *p = strchr(input, '[');
    if (!p) return NULL;

    p = strchr(p + 1, '[');
    if (!p) return NULL;
    ++p;

    int value;
    int status = next_value(&p, &value);
    if (status <= 0) return NULL;

    struct TreeNode *root = new_node(value);

    int cap = 16, head = 0, tail = 0;
    struct TreeNode **queue = (struct TreeNode **)malloc((size_t)cap * sizeof(*queue));
    if (!queue) exit(EXIT_FAILURE);
    queue[tail++] = root;

    while (head < tail) {
        struct TreeNode *node = queue[head++];

        status = next_value(&p, &value);
        if (status == -1) break;
        if (status == 1) {
            node->left = new_node(value);
            if (tail == cap) {
                cap *= 2;
                queue = (struct TreeNode **)realloc(queue, (size_t)cap * sizeof(*queue));
                if (!queue) exit(EXIT_FAILURE);
            }
            queue[tail++] = node->left;
        }

        status = next_value(&p, &value);
        if (status == -1) break;
        if (status == 1) {
            node->right = new_node(value);
            if (tail == cap) {
                cap *= 2;
                queue = (struct TreeNode **)realloc(queue, (size_t)cap * sizeof(*queue));
                if (!queue) exit(EXIT_FAILURE);
            }
            queue[tail++] = node->right;
        }
    }

    free(queue);
    return root;
}

static void free_tree(struct TreeNode *root) {
    if (!root) return;
    int cap = 16, top = 0;
    struct TreeNode **stack = (struct TreeNode **)malloc((size_t)cap * sizeof(*stack));
    if (!stack) exit(EXIT_FAILURE);
    stack[top++] = root;

    while (top > 0) {
        struct TreeNode *node = stack[--top];

        if (node->left) {
            if (top == cap) {
                cap *= 2;
                stack = (struct TreeNode **)realloc(stack, (size_t)cap * sizeof(*stack));
                if (!stack) exit(EXIT_FAILURE);
            }
            stack[top++] = node->left;
        }

        if (node->right) {
            if (top == cap) {
                cap *= 2;
                stack = (struct TreeNode **)realloc(stack, (size_t)cap * sizeof(*stack));
                if (!stack) exit(EXIT_FAILURE);
            }
            stack[top++] = node->right;
        }

        free(node);
    }

    free(stack);
}

int getMinimumDifference(struct TreeNode *root) {
    struct TreeNode *stack[10000];
    int top = 0;
    struct TreeNode *current = root;
    int previous = 0;
    int hasPrevious = 0;
    int answer = INT_MAX;

    while (top > 0 || current != NULL) {
        while (current != NULL) {
            stack[top++] = current;
            current = current->left;
        }

        current = stack[--top];

        if (hasPrevious) {
            int difference = current->val - previous;
            if (difference < answer) answer = difference;
        }

        previous = current->val;
        hasPrevious = 1;
        current = current->right;
    }

    return answer;
}

